        import sailpoint.object.Identity;      
        import sailpoint.api.ObjectUtil;
        import java.util.*;


        log.error("################# WorkGroup details check  ###############");
				log.error("Work Group name in the input: "+ wgName);
        List wrkgmemnberList = new ArrayList();
        Identity workgroup;
        workgroup=context.getObjectByName(Identity.class,wgName);
         if(workgroup==null)
        {
           workgroup=context.getObjectByName(Identity.class,wgName.trim());
        }

        if(workgroup!=null)
        {
        log.error("Work Group Found .............................. ");
        if(workgroup.isWorkgroup()){

          Iterator wrkGrpmembers = ObjectUtil.getWorkgroupMembers(context, workgroup, null);

          // wrkgmemnberList.add("UserName"+ " - "+"Email" + " - "+is Active  );
          while(wrkGrpmembers.hasNext()){
          Object[] object = (Object[]) wrkGrpmembers.next();
          Identity ids = (Identity) object[0];
          wrkgmemnberList.add("[ "+ ids.getName() +" - "+ids.getEmail() + " - "+ids.isInactive() +" ]"  );
          System.out.println(ids.getName()+" - "+ids.isInactive());
          }
         return wrkgmemnberList;
        }
       else 
        return "Not Valid WorkGroup Name";
        }
         else 
        return "Not Valid WorkGroup Name";
